// Keep the policy in code: Jev supplies calibrated signals, the workflow decides.
return $input.all().map((item) => {
  const j = item.json.jev;
  let action = 'pass';
  const reasons = [];

  if (j.jailbreak >= 0.8) reasons.push('jailbreak');
  if (j.harm >= 1.5) reasons.push('high harm');
  if (reasons.length) action = 'block';
  else {
    if (j.contains_pii >= 0.5) reasons.push('contains sensitive data');
    if (j.topic === 'off_topic') reasons.push('off topic');
    if (j.jailbreak >= 0.4) reasons.push('possible jailbreak');
    if (j.harm_confidence < 0.5 || j.topic_confidence < 0.5) reasons.push('low confidence');
    if (reasons.length) action = 'review';
  }

  return { json: { ...item.json, action, reasons } };
});
